import java.io.*;
import java.util.*;

public class OptimizedSolution {
    private static BufferedReader reader;

    static {
        reader = new BufferedReader(new InputStreamReader(System.in));
    }

    public static void main(String[] args) throws Exception {
        String[] input = reader.readLine().trim().split("\\s+");
        int n = Integer.parseInt(input[0]);
        int k = Integer.parseInt(input[1]);

        input = reader.readLine().trim().split("\\s+");
        int[] sequence = new int[n];
        for (int i = 0; i < n; i++) {
            sequence[i] = Integer.parseInt(input[i]);
        }

        int evens = 0, odds = 0;
        List<Integer> validDiffs = new ArrayList<>();

        for (int idx = 0; idx < n; idx++) {
            if (idx > 0 && evens == odds) {
                validDiffs.add(Math.abs(sequence[idx] - sequence[idx - 1]));
            }
            if ((sequence[idx] & 1) == 0) {
                evens++;
            } else {
                odds++;
            }
        }

        validDiffs.sort(null);
        int selections = 0;
        for (int diff : validDiffs) {
            if (k >= diff) {
                selections++;
                k -= diff;
            } else {
                break;
            }
        }
        System.out.println(selections);
    }

    static int computeGCD(int x, int y) {
        while (y != 0) {
            int temp = y;
            y = x % y;
            x = temp;
        }
        return x;
    }

    static int computeLCM(int x, int y) {
        return x / computeGCD(x, y) * y;
    }

    static int modularExponentiation(int base, int exponent, int modulus) {
        if (base == 0) return 0;
        if (exponent == 0) return 1;

        long result = 1;
        base %= modulus;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % modulus;
            }
            base = (base * base) % modulus;
            exponent >>= 1;
        }
        return (int) ((result + modulus) % modulus);
    }
}
